#define main permute_original_main
#include "../permute-cuda/main.cu"
#undef main
#include <vector>
#include <fstream>
#include <cstdint>
#include <cstring>
std::vector<uint32_t>load(const char*n){std::ifstream f(n,std::ios::binary|std::ios::ate);if(!f)exit(3);std::vector<uint32_t>v(f.tellg()/4);f.seekg(0);f.read((char*)v.data(),v.size()*4);return v;}
int main(){auto raw=load("inputs_u32.bin"),gold=load("oracle_u32.bin");const uint32_t guard=0xcafebabe,sentinel=0xdeadbeef;bool all=true;for(int trial=0;trial<=5;trial++){std::vector<uint32_t>prefix,outputs;std::vector<double>times;size_t offset=0,bad=0;bool ok=true;for(auto dims:std::vector<std::vector<int>>{{1,1024,768,12},{2,7,45,5},{2,7,45,5},{1,1,1,1}}){int B=dims[0],T=dims[1],C=dims[2],NH=dims[3],count=3*B*T*C;for(int bs:{32,64,128,256,512,1024}){std::vector<uint32_t>ih(count+32,guard),oh(count+32,guard);std::copy(raw.begin()+offset,raw.begin()+offset+count,ih.begin()+16);std::fill(oh.begin()+16,oh.begin()+16+count,sentinel);float *di,*dout;cudaCheck(cudaMalloc(&di,ih.size()*4));cudaCheck(cudaMalloc(&dout,oh.size()*4));cudaCheck(cudaMemcpy(di,ih.data(),ih.size()*4,cudaMemcpyHostToDevice));cudaCheck(cudaMemcpy(dout,oh.data(),oh.size()*4,cudaMemcpyHostToDevice));auto launch=[&](){permute(dout+16,di+16,B,T,C,NH,bs);};if(trial==0){launch();cudaFree(di);cudaFree(dout);continue;}std::vector<uint32_t>before(oh.size());cudaCheck(cudaMemcpy(before.data(),dout,oh.size()*4,cudaMemcpyDeviceToHost));ok=ok&&before==oh;cudaCheck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<10;rep++)launch();times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/10);std::vector<uint32_t>ai(ih.size()),ao(oh.size());cudaCheck(cudaMemcpy(ai.data(),di,ih.size()*4,cudaMemcpyDeviceToHost));cudaCheck(cudaMemcpy(ao.data(),dout,oh.size()*4,cudaMemcpyDeviceToHost));ok=ok&&ai==ih;for(int i=0;i<count+32;i++){uint32_t ref=i<16||i>=count+16?guard:gold[offset+i-16];bad+=ao[i]!=ref;}prefix.insert(prefix.end(),ai.begin(),ai.end());prefix.insert(prefix.end(),before.begin(),before.end());outputs.insert(outputs.end(),ao.begin(),ao.end());cudaFree(di);cudaFree(dout);}offset+=count;}if(trial==0)continue;ok=ok&&bad==0;all=all&&ok;prefix.insert(prefix.end(),outputs.begin(),outputs.end());std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)prefix.data(),prefix.size()*4);double total=0;for(auto t:times)total+=t;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":null,\"max_rel_error\":null,\"artifact_word_mismatches\":%zu,\"timing_region\":\"sum24_QKV_permutation_launch_sync_R10\",\"jit_excluded\":true,\"path_times_seconds\":[",trial,total,ok?"true":"false",prefix.size(),bad);for(size_t i=0;i<times.size();i++)printf("%s%.12g",i?",":"",times[i]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path.c_str(),prefix.size());}puts(all?"PASS":"FAIL");return all?0:2;}
